import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.regex.Pattern;

import com.example.customers.domain.QueryLog;

import com.microsoft.playwright.Locator;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.web.server.test.LocalServerPort;
import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;

/**
 * The same view, in a real (headless) browser.
 *
 * <p>Two things the browserless test cannot see live here: what the address bar
 * says, and what typing costs the backend — the browser is what decides when a
 * keystroke turns into a request.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListViewBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port + "/";
    }

    @Test
    void filteringNarrowsTheGridAndUpdatesTheAddressBar() {
        assertThat(summary()).hasText("Showing 500 of 500");

        nameInput().fill("vir");

        assertThat(summary()).hasText("Showing 15 of 500");
        assertThat(page).hasURL(Pattern.compile("\\?name=vir$"));
    }

    @Test
    void typingANameCostsOneOrTwoQueries() {
        assertThat(summary()).hasText("Showing 500 of 500");
        queryLog.clear();

        nameInput().pressSequentially("aaltonen",
                new Locator.PressSequentiallyOptions().setDelay(30));

        assertThat(summary()).hasText("Showing 11 of 500");
        int queries = queryLog.countQueries().size() + queryLog.pageQueries().size();
        assertTrue(queries <= 4, "Typing an eight-letter name ran " + queries
                + " queries: " + queryLog.countQueries() + " " + queryLog.pageQueries());
    }

    @Test
    void aLinkWithParametersOpensTheFilteredList() {
        page.navigate(getUrl() + "?name=vir&status=ACTIVE");

        assertThat(summary()).hasText("Showing 5 of 500");
        assertThat(nameInput()).hasValue("vir");
        assertThat(page.locator("vaadin-multi-select-combo-box")).containsText("ACTIVE");
    }

    @Test
    void clearingTheFilterClearsTheParameters() {
        page.navigate(getUrl() + "?name=vir");
        assertThat(summary()).hasText("Showing 15 of 500");

        nameInput().fill("");

        assertThat(summary()).hasText("Showing 500 of 500");
        assertThat(page).hasURL(Pattern.compile("^[^?]*$"));
    }

    private Locator summary() {
        return page.locator("#filter-summary");
    }

    private Locator nameInput() {
        return page.locator("vaadin-text-field input");
    }
}
