+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The criteria a customer has to satisfy to be part of a query's result.
+ *
+ * <p>This is a backend concept: {@link CustomerRepository} applies it while
+ * paging and counting, so a filtered grid still only ever holds one page.
+ *
+ * @param name     free text; split on whitespace into terms, every one of which
+ *                 must occur in the first or the last name. Case and accents are
+ *                 ignored, so {@code makinen} matches {@code Mäkinen}.
+ * @param statuses the statuses to accept; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+
+    /** Combining marks, left behind once a string is decomposed. */
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                // EnumSet iterates in declaration order, which is the order the
+                // statuses appear in the URL.
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** The filter that accepts every customer. */
+    public static CustomerFilter empty() {
+        return EMPTY;
+    }
+
+    /** {@code true} when this filter accepts every customer. */
+    public boolean isEmpty() {
+        return nameTerms().isEmpty() && statuses.isEmpty();
+    }
+
+    /**
+     * The name terms, normalised for comparison: the name text split on
+     * whitespace, lower-cased and stripped of accents.
+     */
+    public List<String> nameTerms() {
+        List<String> terms = new ArrayList<>();
+        for (String term : WHITESPACE.split(name.strip())) {
+            if (!term.isEmpty()) {
+                terms.add(normalize(term));
+            }
+        }
+        return List.copyOf(terms);
+    }
+
+    /**
+     * Returns this filter as a predicate. The name terms are normalised once,
+     * up front, so the predicate can be handed to a whole scan of the data.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        return customer -> matchesStatus(customer) && matchesName(customer, terms);
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
